package main

import (
	"bufio"
	"embed"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

//go:embed src/help.txt src/list.txt
var embedded embed.FS

type options struct {
	help          bool
	version       bool
	list          bool
	unbuffered    bool
	trace         bool
	check         bool
	fail          bool
	filename      string
	lexer         string
	style         string
	formatter     string
	json          bool
	html          bool
	svg           bool
	htmlPrefix    string
	htmlStyles    bool
	htmlAllStyles bool
	htmlOnly      bool
	htmlInline    bool
	htmlTabWidth  int
	htmlLines     bool
	htmlLinesTable bool
	htmlLinesStyle string
	htmlHighlight  string
	htmlHighlightStyle string
	htmlBaseLine   int
	htmlPreventPre bool
	htmlLinkable   bool
	files         []string
}

func defaultOptions() *options {
	return &options{
		lexer:        "autodetect",
		style:        "swapoff",
		formatter:    "terminal",
		htmlTabWidth: 8,
		htmlBaseLine: 1,
	}
}

func die(msg string) {
	fmt.Fprintf(os.Stderr, "executable: error: %s\n", msg)
	os.Exit(80)
}

func parseFlags(args []string) *options {
	opts := defaultOptions()

	boolFlags := map[string]*bool{
		"--help":                      &opts.help,
		"-h":                          &opts.help,
		"--version":                   &opts.version,
		"--list":                      &opts.list,
		"--unbuffered":                &opts.unbuffered,
		"--trace":                     &opts.trace,
		"--check":                     &opts.check,
		"--fail":                      &opts.fail,
		"--json":                      &opts.json,
		"--html":                      &opts.html,
		"--svg":                       &opts.svg,
		"--html-styles":               &opts.htmlStyles,
		"--html-all-styles":           &opts.htmlAllStyles,
		"--html-only":                 &opts.htmlOnly,
		"--html-inline-styles":        &opts.htmlInline,
		"--html-lines":                &opts.htmlLines,
		"--html-lines-table":          &opts.htmlLinesTable,
		"--html-prevent-surrounding-pre": &opts.htmlPreventPre,
		"--html-linkable-lines":       &opts.htmlLinkable,
	}
	stringFlags := map[string]*string{
		"--filename":             &opts.filename,
		"--lexer":                &opts.lexer,
		"-l":                     &opts.lexer,
		"--style":                &opts.style,
		"-s":                     &opts.style,
		"--formatter":            &opts.formatter,
		"-f":                     &opts.formatter,
		"--html-prefix":          &opts.htmlPrefix,
		"--html-lines-style":     &opts.htmlLinesStyle,
		"--html-highlight":       &opts.htmlHighlight,
		"--html-highlight-style": &opts.htmlHighlightStyle,
	}
	intFlags := map[string]*int{
		"--html-tab-width": &opts.htmlTabWidth,
		"--html-base-line": &opts.htmlBaseLine,
	}

	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			opts.files = append(opts.files, args[i+1:]...)
			break
		}

		// Check if it's a flag
		if strings.HasPrefix(a, "-") && a != "-" {
			// Detect embedded value: --name=value
			eqIdx := strings.Index(a, "=")
			var name, val string
			hasEq := false
			if eqIdx >= 0 {
				name = a[:eqIdx]
				val = a[eqIdx+1:]
				hasEq = true
			} else {
				name = a
			}

			if bp, ok := boolFlags[name]; ok {
				if hasEq {
					die(fmt.Sprintf("unknown flag %s", a))
				}
				*bp = true
				i++
				continue
			}
			if sp, ok := stringFlags[name]; ok {
				if hasEq {
					*sp = val
					i++
					continue
				}
				if i+1 >= len(args) {
					die(fmt.Sprintf("--%s requires an argument", name))
				}
				*sp = args[i+1]
				i += 2
				continue
			}
			if ip, ok := intFlags[name]; ok {
				var s string
				if hasEq {
					s = val
					i++
				} else {
					if i+1 >= len(args) {
						die(fmt.Sprintf("--%s requires an argument", name))
					}
					s = args[i+1]
					i += 2
				}
				var n int
				_, err := fmt.Sscanf(s, "%d", &n)
				if err != nil {
					die(fmt.Sprintf("invalid value for %s: %q", name, s))
				}
				*ip = n
				continue
			}
			die(fmt.Sprintf("unknown flag %s", name))
		}

		// Positional
		opts.files = append(opts.files, a)
		i++
	}
	return opts
}

func printHelp() {
	b, _ := embedded.ReadFile("src/help.txt")
	os.Stdout.Write(b)
}

func printList() {
	b, _ := embedded.ReadFile("src/list.txt")
	os.Stdout.Write(b)
}

func readFileOrDie(f string) []byte {
	wd, _ := os.Getwd()
	full := f
	if !filepath.IsAbs(full) {
		full = filepath.Join(wd, f)
	}
	b, err := os.ReadFile(full)
	if err != nil {
		die(fmt.Sprintf("[<files> ...]: stat %s: no such file or directory", full))
	}
	return b
}

func main() {
	opts := parseFlags(os.Args[1:])

	if opts.help {
		printHelp()
		return
	}
	if opts.version {
		fmt.Println("?-?-?")
		return
	}
	if opts.list {
		printList()
		return
	}

	// Load style (default is swapoff, which is not in the binary; causes error).
	if err := ensureStyle(opts.style); err != nil {
		fmt.Fprintf(os.Stderr, "executable: error: %s\n", err.Error())
		os.Exit(1)
	}

	// Choose formatter
	formatterName := opts.formatter
	if opts.json {
		formatterName = "json"
	}
	if opts.html {
		formatterName = "html"
	}
	if opts.svg {
		formatterName = "svg"
	}

	// Gather input
	var inputs []inputSource
	if len(opts.files) == 0 {
		// Read from stdin
		data, _ := io.ReadAll(os.Stdin)
		name := opts.filename
		inputs = append(inputs, inputSource{name: name, data: data})
	} else {
		for _, f := range opts.files {
			data := readFileOrDie(f)
			inputs = append(inputs, inputSource{name: f, data: data})
		}
	}

	out := bufio.NewWriter(os.Stdout)
	if opts.unbuffered {
		for _, in := range inputs {
			processOne(os.Stdout, in, opts, formatterName)
		}
		return
	}
	defer out.Flush()
	for _, in := range inputs {
		processOne(out, in, opts, formatterName)
	}
}

type inputSource struct {
	name string
	data []byte
}

func ensureStyle(name string) error {
	if _, ok := styles[name]; ok {
		return nil
	}
	// Try to read as a file
	if _, err := os.Stat(name); err == nil {
		return nil
	}
	return fmt.Errorf("open %s: no such file or directory", name)
}

func processOne(w io.Writer, in inputSource, opts *options, formatterName string) {
	lexerName := opts.lexer
	if lexerName == "autodetect" {
		lexerName = detectLexer(in.name, in.data)
	}
	if opts.fail && (lexerName == "autodetect" || lexerName == "plaintext" || lexerName == "") {
		os.Exit(1)
	}

	tokens := lex(lexerName, string(in.data), opts)

	switch formatterName {
	case "noop":
		formatNoop(w, tokens)
	case "tokens":
		formatTokens(w, tokens)
	case "json":
		formatJSON(w, tokens)
	case "terminal", "terminal8", "terminal16", "terminal256", "terminal16m":
		formatTerminal(w, tokens, opts.style, formatterName)
	case "html":
		formatHTML(w, tokens, opts)
	case "svg":
		formatSVG(w, tokens, opts.style)
	default:
		die(fmt.Sprintf("unknown formatter %q", formatterName))
	}
}
GOEOF

