package main

import (
	"path/filepath"
	"strings"
)

// Token type names that appear in the output. We only define the ones used
// by the plaintext / fallback path.
type Token struct {
	Type  string
	Value string
}

// lex tokenises the input. We only implement the plaintext lexer (every
// other lexer degrades to plaintext, which is the autodetect fallback).
func lex(lexerName, source string, opts *options) []Token {
	// Plaintext: a Text token per line, splitting on newlines.
	return lexPlaintext(source)
}

// lexPlaintext emits one Text token per line. A line ending with '\n' keeps
// the newline in the token value. This mirrors the observed behavior of
// Chroma's plaintext lexer on simple inputs.
func lexPlaintext(source string) []Token {
	if source == "" {
		return nil
	}
	var out []Token
	i := 0
	for i < len(source) {
		j := strings.IndexByte(source[i:], '\n')
		if j < 0 {
			out = append(out, Token{Type: "Text", Value: source[i:]})
			break
		}
		end := i + j + 1
		out = append(out, Token{Type: "Text", Value: source[i:end]})
		i = end
	}
	// Merge consecutive Text tokens (observed behavior: a single token).
	if len(out) > 1 {
		merged := []Token{{Type: "Text", Value: source}}
		return merged
	}
	return out
}

// detectLexer returns a lexer name based on the filename.
// For the purposes of this re-implementation, we always return "plaintext"
// when no extension is recognized.
func detectLexer(filename string, data []byte) string {
	if filename == "" {
		return "plaintext"
	}
	base := filepath.Base(filename)
	_ = base
	return "plaintext"
}
GOEOF

