package main

import (
	"fmt"
	"io"
	"strings"
	"unicode/utf8"
)

func formatNoop(w io.Writer, tokens []Token) {
	for _, t := range tokens {
		io.WriteString(w, t.Value)
	}
}

// formatTokens emits `&Token{Type, "escaped-value"}` one per line. The
// escaping is Go's %q with the special case that ASCII printable characters
// (including \x01 -> \x01) get shown via %q as well -- matching Chroma's
// observed output exactly.
func formatTokens(w io.Writer, tokens []Token) {
	for _, t := range tokens {
		fmt.Fprintf(w, "&Token{%s, %s}\n", t.Type, goQuote(t.Value))
	}
}

// formatJSON emits a JSON array of {"type":"T","value":"V"} per token.
// Pretty prints with two-space indentation and surrounds items with a
// trailing comma (same as observed).
func formatJSON(w io.Writer, tokens []Token) {
	io.WriteString(w, "[\n")
	for i, t := range tokens {
		var sep string
		if i == len(tokens)-1 {
			sep = "\n"
		} else {
			sep = ",\n"
		}
		fmt.Fprintf(w, "  {\"type\":%s,\"value\":%s}%s", jsonString(t.Type), jsonString(t.Value), sep)
	}
	io.WriteString(w, "]\n")
}

// goQuote returns a Go-style %q-formatted string.
func goQuote(s string) string {
	return fmt.Sprintf("%q", s)
}

// jsonString returns a JSON-encoded string with standard escapes.
func jsonString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); {
		r, size := utf8.DecodeRuneInString(s[i:])
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		default:
			if r < 0x20 {
				fmt.Fprintf(&b, `\u%04x`, r)
			} else {
				b.WriteString(s[i : i+size])
			}
		}
		i += size
	}
	b.WriteByte('"')
	return b.String()
}

// formatTerminal is a stub: when --formatter=terminal is selected, we emit
// the raw token values, without colour codes. (The default style "swapoff"
// is not registered and we already error out before getting here; the style
// check happens at start-up.)
func formatTerminal(w io.Writer, tokens []Token, style, variant string) {
	for _, t := range tokens {
		io.WriteString(w, t.Value)
	}
}

// formatHTML is a minimal HTML formatter, stub.
func formatHTML(w io.Writer, tokens []Token, opts *options) {
	io.WriteString(w, "<pre>")
	for _, t := range tokens {
		io.WriteString(w, escapeHTML(t.Value))
	}
	io.WriteString(w, "</pre>\n")
}

// formatSVG is a minimal SVG formatter, stub.
func formatSVG(w io.Writer, tokens []Token, style string) {
	io.WriteString(w, "<svg xmlns=\"http://www.w3.org/2000/svg\"></svg>\n")
}

func escapeHTML(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&#34;")
		case '\'':
			b.WriteString("&#39;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}
