package main

import (
	"bufio"
	"embed"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

//go:embed src/help.txt src/list.txt
var embedded embed.FS

type options struct {
	help               bool
	version            bool
	list               bool
	unbuffered         bool
	trace              bool
	check              bool
	fail               bool
	filename           string
	lexer              string
	style              string
	formatter          string
	json               bool
	html               bool
	svg                bool
	htmlPrefix         string
	htmlStyles         bool
	htmlAllStyles      bool
	htmlOnly           bool
	htmlInline         bool
	htmlTabWidth       int
	htmlLines          bool
	htmlLinesTable     bool
	htmlLinesStyle     string
	htmlHighlight      string
	htmlHighlightStyle string
	htmlBaseLine       int
	htmlPreventPre     bool
	htmlLinkable       bool
	files              []string
}

func defaultOptions() *options {
	return &options{
		lexer:        "autodetect",
		style:        "swapoff",
		formatter:    "terminal",
		htmlTabWidth: 8,
		htmlBaseLine: 1,
	}
}

func exitFatal(code int, format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "executable: error: "+format+"\n", args...)
	os.Exit(code)
}

// parseFlags parses the CLI; on syntactic error it exits with code 80.
func parseFlags(args []string) *options {
	opts := defaultOptions()

	type flagKind int
	const (
		kindBool flagKind = iota
		kindString
		kindInt
	)

	type flagSpec struct {
		kind   flagKind
		bp     *bool
		sp     *string
		ip     *int
	}

	specs := map[string]flagSpec{
		"--help":                         {kind: kindBool, bp: &opts.help},
		"-h":                             {kind: kindBool, bp: &opts.help},
		"--version":                      {kind: kindBool, bp: &opts.version},
		"--list":                         {kind: kindBool, bp: &opts.list},
		"--unbuffered":                   {kind: kindBool, bp: &opts.unbuffered},
		"--trace":                        {kind: kindBool, bp: &opts.trace},
		"--check":                        {kind: kindBool, bp: &opts.check},
		"--fail":                         {kind: kindBool, bp: &opts.fail},
		"--json":                         {kind: kindBool, bp: &opts.json},
		"--html":                         {kind: kindBool, bp: &opts.html},
		"--svg":                          {kind: kindBool, bp: &opts.svg},
		"--html-styles":                  {kind: kindBool, bp: &opts.htmlStyles},
		"--html-all-styles":              {kind: kindBool, bp: &opts.htmlAllStyles},
		"--html-only":                    {kind: kindBool, bp: &opts.htmlOnly},
		"--html-inline-styles":           {kind: kindBool, bp: &opts.htmlInline},
		"--html-lines":                   {kind: kindBool, bp: &opts.htmlLines},
		"--html-lines-table":             {kind: kindBool, bp: &opts.htmlLinesTable},
		"--html-prevent-surrounding-pre": {kind: kindBool, bp: &opts.htmlPreventPre},
		"--html-linkable-lines":          {kind: kindBool, bp: &opts.htmlLinkable},

		"--filename":             {kind: kindString, sp: &opts.filename},
		"--lexer":                {kind: kindString, sp: &opts.lexer},
		"-l":                     {kind: kindString, sp: &opts.lexer},
		"--style":                {kind: kindString, sp: &opts.style},
		"-s":                     {kind: kindString, sp: &opts.style},
		"--formatter":            {kind: kindString, sp: &opts.formatter},
		"-f":                     {kind: kindString, sp: &opts.formatter},
		"--html-prefix":          {kind: kindString, sp: &opts.htmlPrefix},
		"--html-lines-style":     {kind: kindString, sp: &opts.htmlLinesStyle},
		"--html-highlight":       {kind: kindString, sp: &opts.htmlHighlight},
		"--html-highlight-style": {kind: kindString, sp: &opts.htmlHighlightStyle},

		"--html-tab-width": {kind: kindInt, ip: &opts.htmlTabWidth},
		"--html-base-line": {kind: kindInt, ip: &opts.htmlBaseLine},
	}

	setBoolFromEq := func(name, val string) {
		v := strings.ToLower(val)
		switch v {
		case "true", "1", "yes":
			*specs[name].bp = true
		case "false", "0", "no":
			*specs[name].bp = false
		default:
			exitFatal(80, "invalid value for %s: %q", name, val)
		}
	}

	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			opts.files = append(opts.files, args[i+1:]...)
			break
		}

		if strings.HasPrefix(a, "-") && a != "-" {
			eqIdx := strings.Index(a, "=")
			var name, val string
			hasEq := false
			if eqIdx >= 0 {
				name = a[:eqIdx]
				val = a[eqIdx+1:]
				hasEq = true
			} else {
				name = a
			}

			sp, ok := specs[name]
			if !ok {
				exitFatal(80, "unknown flag %s", name)
			}

			switch sp.kind {
			case kindBool:
				if hasEq {
					setBoolFromEq(name, val)
				} else {
					*sp.bp = true
				}
				i++
			case kindString:
				if hasEq {
					*sp.sp = val
					i++
				} else {
					if i+1 >= len(args) {
						exitFatal(80, "expected argument for %s", name)
					}
					*sp.sp = args[i+1]
					i += 2
				}
			case kindInt:
				var s string
				if hasEq {
					s = val
					i++
				} else {
					if i+1 >= len(args) {
						exitFatal(80, "expected argument for %s", name)
					}
					s = args[i+1]
					i += 2
				}
				n, err := strconv.Atoi(s)
				if err != nil {
					exitFatal(80, "invalid value for %s: %q", name, s)
				}
				*sp.ip = n
			}
			continue
		}

		opts.files = append(opts.files, a)
		i++
	}
	return opts
}

func printHelp() {
	b, _ := embedded.ReadFile("src/help.txt")
	os.Stdout.Write(b)
}

func printList() {
	b, _ := embedded.ReadFile("src/list.txt")
	os.Stdout.Write(b)
}

// validateFiles checks that all positional file arguments refer to existing files.
// Returns an error with the kong-like "[<files> ...]: stat X: no such file or directory"
// message. This is independent from the actual I/O performed later.
func validateFiles(files []string) error {
	wd, _ := os.Getwd()
	for _, f := range files {
		path := f
		if !filepath.IsAbs(path) {
			path = filepath.Join(wd, f)
		}
		if _, err := os.Stat(path); err != nil {
			return fmt.Errorf("[<files> ...]: stat %s: no such file or directory", path)
		}
	}
	return nil
}

var formatterNames = []string{
	"html", "json", "noop", "svg",
	"terminal", "terminal16", "terminal16m", "terminal256", "terminal8",
	"tokens",
}

func validateFormatter(name string) error {
	for _, n := range formatterNames {
		if n == name {
			return nil
		}
	}
	return fmt.Errorf("unknown formatter %q", name)
}

func main() {
	opts := parseFlags(os.Args[1:])

	if opts.help {
		printHelp()
		return
	}
	if opts.version {
		fmt.Println("?-?-?")
		return
	}
	if opts.list {
		printList()
		return
	}

	// Load style (default swapoff is not built-in; causes error).
	if err := ensureStyle(opts.style); err != nil {
		fmt.Fprintf(os.Stderr, "executable: error: %s\n", err.Error())
		os.Exit(1)
	}

	// Validate positional files.
	if err := validateFiles(opts.files); err != nil {
		exitFatal(80, "%s", err.Error())
	}

	// Determine formatter from convenience flags.
	formatterName := opts.formatter
	if opts.json {
		formatterName = "json"
	}
	if opts.html {
		formatterName = "html"
	}
	if opts.svg {
		formatterName = "svg"
	}
	if err := validateFormatter(formatterName); err != nil {
		exitFatal(80, "%s", err.Error())
	}

	// Gather input.
	var inputs []inputSource
	if len(opts.files) == 0 {
		data, _ := io.ReadAll(os.Stdin)
		name := opts.filename
		inputs = append(inputs, inputSource{name: name, data: data})
	} else {
		for _, f := range opts.files {
			data, err := os.ReadFile(f)
			if err != nil {
				exitFatal(1, "%s", err.Error())
			}
			inputs = append(inputs, inputSource{name: f, data: data})
		}
	}

	out := bufio.NewWriter(os.Stdout)
	if opts.unbuffered {
		for _, in := range inputs {
			processOne(os.Stdout, in, opts, formatterName)
		}
		return
	}
	defer out.Flush()
	for _, in := range inputs {
		processOne(out, in, opts, formatterName)
	}
}

type inputSource struct {
	name string
	data []byte
}

func ensureStyle(name string) error {
	if _, ok := styles[name]; ok {
		return nil
	}
	if _, err := os.Stat(name); err == nil {
		return nil
	}
	return fmt.Errorf("open %s: no such file or directory", name)
}

func processOne(w io.Writer, in inputSource, opts *options, formatterName string) {
	lexerName := opts.lexer
	if lexerName == "autodetect" {
		lexerName = detectLexer(in.name, in.data)
	}
	if opts.fail {
		// In autodetect mode, if we could not find a specific lexer (i.e.
		// ended up at plaintext), exit silently with status 1.
		if lexerName == "" || lexerName == "plaintext" || lexerName == "autodetect" {
			os.Exit(1)
		}
	}
	tokens := lex(lexerName, string(in.data), opts)

	switch formatterName {
	case "noop":
		formatNoop(w, tokens)
	case "tokens":
		formatTokens(w, tokens)
	case "json":
		formatJSON(w, tokens)
	case "terminal", "terminal8", "terminal16", "terminal256", "terminal16m":
		formatTerminal(w, tokens, opts.style, formatterName)
	case "html":
		formatHTML(w, tokens, opts)
	case "svg":
		formatSVG(w, tokens, opts.style)
	}
}
